import{_ as t,o as d,c as e,Q as o}from"./chunks/framework.48927342.js";const f=JSON.parse('{"title":"Common Prepositions and Their Uses","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/08-prepositions.md","filePath":"en/more/maltese/grammar/08-prepositions.md"}'),a={name:"en/more/maltese/grammar/08-prepositions.md"},i=o('<h1 id="common-prepositions-and-their-uses" tabindex="-1">Common Prepositions and Their Uses <a class="header-anchor" href="#common-prepositions-and-their-uses" aria-label="Permalink to &quot;Common Prepositions and Their Uses&quot;">​</a></h1><p>Prepositions are used with nouns and definite articles; some contract with the following article. Prepositions can also take person suffixes, creating forms such as “to me,” “with you,” or “at his place.” The list is ordered approximately by everyday frequency. Dictionaries may also list rare dialectal, archaic, conjunction-like, and inflected forms; this chapter focuses on useful prepositions and phrases in modern standard Maltese.</p><h2 id="_1-common-prepositions" tabindex="-1">1. Common Prepositions <a class="header-anchor" href="#_1-common-prepositions" aria-label="Permalink to &quot;1. Common Prepositions&quot;">​</a></h2><table><thead><tr><th>Malti</th><th>English meaning</th><th>Use/collocation</th></tr></thead><tbody><tr><td>f&#39; / fi</td><td>in; at</td><td><code>fil-kamra</code>: in the room; <code>f&#39;Malta</code>: in Malta</td></tr><tr><td>b&#39; / bi</td><td>with; by; using</td><td><code>b&#39;idek</code>: with your hand; <code>bi flus</code>: with money (<code>bi</code> is common before consonant clusters)</td></tr><tr><td>ma&#39;</td><td>with</td><td><code>ma&#39; ħabib</code>: with a friend</td></tr><tr><td>għal</td><td>for; to; toward</td><td><code>għalik</code>: for you; <code>għal Malta</code>: to/toward Malta, depending on context</td></tr><tr><td>minn</td><td>from; than</td><td><code>minn Malta</code>: from Malta</td></tr><tr><td>ta&#39;</td><td>of; belonging to</td><td><code>bieb ta&#39; dar</code>: the door of a house</td></tr><tr><td>fuq</td><td>on; about</td><td><code>fuq il-mejda</code>: on the table</td></tr><tr><td>lil</td><td>to; for (a person)</td><td><code>lil ommi</code>: to/for my mother</td></tr><tr><td>għand</td><td>at someone&#39;s place; with; have</td><td><code>għandi ktieb</code>: I have a book; <code>għand it-tabib</code>: at the doctor&#39;s</td></tr><tr><td>wara</td><td>behind; after</td><td><code>wara l-ikla</code>: after the meal</td></tr><tr><td>sa</td><td>until; as far as</td><td><code>sa għada</code>: until tomorrow</td></tr><tr><td>lejn</td><td>toward</td><td><code>lejn il-port</code>: toward the port</td></tr><tr><td>taħt</td><td>under</td><td><code>taħt is-siġġu</code>: under the chair</td></tr><tr><td>bejn</td><td>between</td><td><code>bejn iż-żewġt idjar</code>: between the two houses</td></tr><tr><td>qabel</td><td>before</td><td><code>qabel ix-xogħol</code>: before work</td></tr><tr><td>ħdejn</td><td>beside; next to</td><td><code>ħdejn l-iskola</code>: next to the school</td></tr><tr><td>quddiem</td><td>in front of</td><td><code>quddiem id-dar</code>: in front of the house</td></tr><tr><td>madwar</td><td>around; about</td><td><code>madwar il-mejda</code>: around the table</td></tr><tr><td>dwar</td><td>about; concerning</td><td><code>ktieb dwar Malta</code>: a book about Malta</td></tr><tr><td>minħabba</td><td>because of</td><td><code>minħabba x-xita</code>: because of the rain</td></tr><tr><td>bħal</td><td>like; as</td><td><code>bħal dan</code>: like this</td></tr><tr><td>ġewwa</td><td>inside; into</td><td><code>ġewwa d-dar</code>: inside the house</td></tr><tr><td>barra</td><td>outside; out of</td><td><code>barra mid-dar</code>: outside the house</td></tr><tr><td>mingħajr</td><td>without</td><td><code>mingħajr zokkor</code>: without sugar</td></tr><tr><td>kontra</td><td>against</td><td><code>kontra l-ħajt</code>: against the wall</td></tr><tr><td>skont</td><td>according to</td><td><code>skont ir-regoli</code>: according to the rules</td></tr><tr><td>tul</td><td>along; during; throughout</td><td><code>tul it-triq</code>: along the road</td></tr></tbody></table><h3 id="other-common-prepositions-and-fixed-phrases" tabindex="-1">Other Common Prepositions and Fixed Phrases <a class="header-anchor" href="#other-common-prepositions-and-fixed-phrases" aria-label="Permalink to &quot;Other Common Prepositions and Fixed Phrases&quot;">​</a></h3><table><thead><tr><th>Malti</th><th>English meaning</th><th>Use/collocation</th></tr></thead><tbody><tr><td>bla</td><td>without; lacking (before a bare noun)</td><td><code>bla ħalib</code>: without milk; <code>mingħajr</code> is more common in negative-preposition phrases</td></tr><tr><td>bħala</td><td>as; in the capacity of</td><td><code>bħala għalliem</code>: as a teacher</td></tr><tr><td>biswit</td><td>opposite; across from</td><td><code>biswit l-iskola</code>: opposite the school</td></tr><tr><td>faċċata ta&#39;</td><td>facing; opposite</td><td><code>faċċata tal-iskola</code>: opposite the school</td></tr><tr><td>flok</td><td>instead of; in place of</td><td><code>flok kafè</code>: instead of coffee</td></tr><tr><td>fost</td><td>among</td><td><code>fost il-ħbieb</code>: among friends</td></tr><tr><td>ġo</td><td>inside; into (contracted form related to <code>ġewwa</code>)</td><td><code>ġo borża</code>: in a bag</td></tr><tr><td>għajr</td><td>except; other than</td><td><code>kulħadd għajr Ana</code>: everyone except Ana</td></tr><tr><td>ħlief</td><td>except; but</td><td><code>xejn ħlief ktieb</code>: nothing but a book</td></tr><tr><td>maġenb</td><td>next to; beside</td><td><code>maġenb id-dar</code>: next to the house</td></tr><tr><td>matul</td><td>during; throughout; along</td><td><code>matul il-festa</code>: during the festival, usually over an extended period</td></tr><tr><td>minflok</td><td>instead of</td><td><code>minflok il-karozza</code>: instead of the car</td></tr><tr><td>minkejja</td><td>despite; in spite of</td><td><code>minkejja x-xita</code>: despite the rain</td></tr><tr><td>qalb</td><td>amid; in the middle of</td><td><code>qalb il-belt</code>: in the city centre</td></tr><tr><td>qrib</td><td>near</td><td><code>qrib l-iskola</code>: near the school</td></tr><tr><td>sakemm</td><td>until</td><td><code>sakemm tasal</code>: until you arrive</td></tr><tr><td>waqt</td><td>at the time of; during</td><td><code>waqt il-laqgħa</code>: during the meeting, emphasizing overlap in time</td></tr></tbody></table><h2 id="_2-definite-article-combinations-and-contractions" tabindex="-1">2. Definite-Article Combinations and Contractions <a class="header-anchor" href="#_2-definite-article-combinations-and-contractions" aria-label="Permalink to &quot;2. Definite-Article Combinations and Contractions&quot;">​</a></h2><p>The basic Maltese definite article is <code>il-</code>; before vowels or certain consonants, it may appear as <code>l-</code>, <code>is-</code>, <code>id-</code>, <code>it-</code>, and other forms. Each cell below shows how the preposition combines with one of the five article forms requested. A hyphen indicates a contraction; a space indicates that the words are not contracted. Attach a noun stem to the final hyphen, for example <code>fil-kamra</code> and <code>fuq is-suq</code>. <code>bla</code> normally takes a bare noun, and <code>sakemm</code> normally introduces a clause, so neither is mechanically combined with these article forms.</p><table><thead><tr><th>Preposition/phrase</th><th>English meaning</th><th>+ il-</th><th>+ l-</th><th>+ is-</th><th>+ id-</th><th>+ it-</th></tr></thead><tbody><tr><td>f&#39; / fi</td><td>in; at</td><td><code>fil-</code></td><td><code>fl-</code></td><td><code>fis-</code></td><td><code>fid-</code></td><td><code>fit-</code></td></tr><tr><td>b&#39; / bi</td><td>with; by</td><td><code>bil-</code></td><td><code>bl-</code></td><td><code>bis-</code></td><td><code>bid-</code></td><td><code>bit-</code></td></tr><tr><td>ma&#39;</td><td>with</td><td><code>mal-</code></td><td><code>mal-</code></td><td><code>mas-</code></td><td><code>mad-</code></td><td><code>mat-</code></td></tr><tr><td>għal</td><td>for; to; toward</td><td><code>għall-</code></td><td><code>għall-</code></td><td><code>għas-</code></td><td><code>għad-</code></td><td><code>għat-</code></td></tr><tr><td>minn</td><td>from; than</td><td><code>mill-</code></td><td><code>mill-</code></td><td><code>mis-</code></td><td><code>mid-</code></td><td><code>mit-</code></td></tr><tr><td>ta&#39;</td><td>of; belonging to</td><td><code>tal-</code></td><td><code>tal-</code></td><td><code>tas-</code></td><td><code>tad-</code></td><td><code>tat-</code></td></tr><tr><td>fuq</td><td>on; about</td><td><code>fuq il-</code></td><td><code>fuq l-</code></td><td><code>fuq is-</code></td><td><code>fuq id-</code></td><td><code>fuq it-</code></td></tr><tr><td>lil</td><td>to/for a person</td><td><code>lill-</code></td><td><code>lill-</code></td><td><code>lis-</code></td><td><code>lid-</code></td><td><code>lit-</code></td></tr><tr><td>għand</td><td>at; have</td><td><code>għand il-</code></td><td><code>għand l-</code></td><td><code>għand is-</code></td><td><code>għand id-</code></td><td><code>għand it-</code></td></tr><tr><td>wara</td><td>behind; after</td><td><code>wara l-</code></td><td><code>wara l-</code></td><td><code>wara s-</code></td><td><code>wara d-</code></td><td><code>wara t-</code></td></tr><tr><td>sa</td><td>until; as far as</td><td><code>sal-</code></td><td><code>sal-</code></td><td><code>sas-</code></td><td><code>sad-</code></td><td><code>sat-</code></td></tr><tr><td>lejn</td><td>toward</td><td><code>lejn il-</code></td><td><code>lejn l-</code></td><td><code>lejn is-</code></td><td><code>lejn id-</code></td><td><code>lejn it-</code></td></tr><tr><td>taħt</td><td>under</td><td><code>taħt il-</code></td><td><code>taħt l-</code></td><td><code>taħt is-</code></td><td><code>taħt id-</code></td><td><code>taħt it-</code></td></tr><tr><td>bejn</td><td>between</td><td><code>bejn il-</code></td><td><code>bejn l-</code></td><td><code>bejn is-</code></td><td><code>bejn id-</code></td><td><code>bejn it-</code></td></tr><tr><td>qabel</td><td>before</td><td><code>qabel il-</code></td><td><code>qabel l-</code></td><td><code>qabel is-</code></td><td><code>qabel id-</code></td><td><code>qabel it-</code></td></tr><tr><td>ħdejn</td><td>beside; next to</td><td><code>ħdejn il-</code></td><td><code>ħdejn l-</code></td><td><code>ħdejn is-</code></td><td><code>ħdejn id-</code></td><td><code>ħdejn it-</code></td></tr><tr><td>quddiem</td><td>in front of</td><td><code>quddiem il-</code></td><td><code>quddiem l-</code></td><td><code>quddiem is-</code></td><td><code>quddiem id-</code></td><td><code>quddiem it-</code></td></tr><tr><td>madwar</td><td>around; about</td><td><code>madwar il-</code></td><td><code>madwar l-</code></td><td><code>madwar is-</code></td><td><code>madwar id-</code></td><td><code>madwar it-</code></td></tr><tr><td>dwar</td><td>about; concerning</td><td><code>dwar il-</code></td><td><code>dwar l-</code></td><td><code>dwar is-</code></td><td><code>dwar id-</code></td><td><code>dwar it-</code></td></tr><tr><td>minħabba</td><td>because of</td><td><code>minħabba l-</code></td><td><code>minħabba l-</code></td><td><code>minħabba s-</code></td><td><code>minħabba d-</code></td><td><code>minħabba t-</code></td></tr><tr><td>bħal</td><td>like; as</td><td><code>bħall-</code></td><td><code>bħall-</code></td><td><code>bħas-</code></td><td><code>bħad-</code></td><td><code>bħat-</code></td></tr><tr><td>ġewwa</td><td>inside; into</td><td><code>ġewwa l-</code></td><td><code>ġewwa l-</code></td><td><code>ġewwa s-</code></td><td><code>ġewwa d-</code></td><td><code>ġewwa t-</code></td></tr><tr><td>barra</td><td>outside; out of</td><td><code>barra mill-</code></td><td><code>barra mill-</code></td><td><code>barra mis-</code></td><td><code>barra mid-</code></td><td><code>barra mit-</code></td></tr><tr><td>mingħajr</td><td>without</td><td><code>mingħajr il-</code></td><td><code>mingħajr l-</code></td><td><code>mingħajr is-</code></td><td><code>mingħajr id-</code></td><td><code>mingħajr it-</code></td></tr><tr><td>kontra</td><td>against</td><td><code>kontra l-</code></td><td><code>kontra l-</code></td><td><code>kontra s-</code></td><td><code>kontra d-</code></td><td><code>kontra t-</code></td></tr><tr><td>skont</td><td>according to</td><td><code>skont il-</code></td><td><code>skont l-</code></td><td><code>skont is-</code></td><td><code>skont id-</code></td><td><code>skont it-</code></td></tr><tr><td>tul</td><td>along; throughout</td><td><code>tul il-</code></td><td><code>tul l-</code></td><td><code>tul is-</code></td><td><code>tul id-</code></td><td><code>tul it-</code></td></tr><tr><td>bla</td><td>without</td><td>normally no article</td><td>normally no article</td><td>normally no article</td><td>normally no article</td><td>normally no article</td></tr><tr><td>bħala</td><td>as</td><td><code>bħala l-</code></td><td><code>bħala l-</code></td><td><code>bħala s-</code></td><td><code>bħala d-</code></td><td><code>bħala t-</code></td></tr><tr><td>biswit</td><td>opposite</td><td><code>biswit il-</code></td><td><code>biswit l-</code></td><td><code>biswit is-</code></td><td><code>biswit id-</code></td><td><code>biswit it-</code></td></tr><tr><td>faċċata ta&#39;</td><td>facing; opposite</td><td><code>faċċata tal-</code></td><td><code>faċċata tal-</code></td><td><code>faċċata tas-</code></td><td><code>faċċata tad-</code></td><td><code>faċċata tat-</code></td></tr><tr><td>flok</td><td>instead of</td><td><code>flok il-</code></td><td><code>flok l-</code></td><td><code>flok is-</code></td><td><code>flok id-</code></td><td><code>flok it-</code></td></tr><tr><td>fost</td><td>among</td><td><code>fost il-</code></td><td><code>fost l-</code></td><td><code>fost is-</code></td><td><code>fost id-</code></td><td><code>fost it-</code></td></tr><tr><td>ġo</td><td>inside; into</td><td><code>ġol-</code></td><td><code>ġol-</code></td><td><code>ġos-</code></td><td><code>ġod-</code></td><td><code>ġot-</code></td></tr><tr><td>għajr</td><td>except</td><td><code>għajr il-</code></td><td><code>għajr l-</code></td><td><code>għajr is-</code></td><td><code>għajr id-</code></td><td><code>għajr it-</code></td></tr><tr><td>ħlief</td><td>except; but</td><td><code>ħlief il-</code></td><td><code>ħlief l-</code></td><td><code>ħlief is-</code></td><td><code>ħlief id-</code></td><td><code>ħlief it-</code></td></tr><tr><td>maġenb</td><td>next to; beside</td><td><code>maġenb il-</code></td><td><code>maġenb l-</code></td><td><code>maġenb is-</code></td><td><code>maġenb id-</code></td><td><code>maġenb it-</code></td></tr><tr><td>matul</td><td>during; throughout</td><td><code>matul il-</code></td><td><code>matul l-</code></td><td><code>matul is-</code></td><td><code>matul id-</code></td><td><code>matul it-</code></td></tr><tr><td>minflok</td><td>instead of</td><td><code>minflok il-</code></td><td><code>minflok l-</code></td><td><code>minflok is-</code></td><td><code>minflok id-</code></td><td><code>minflok it-</code></td></tr><tr><td>minkejja</td><td>despite</td><td><code>minkejja l-</code></td><td><code>minkejja l-</code></td><td><code>minkejja s-</code></td><td><code>minkejja d-</code></td><td><code>minkejja t-</code></td></tr><tr><td>qalb</td><td>amid; in the middle of</td><td><code>qalb il-</code></td><td><code>qalb l-</code></td><td><code>qalb is-</code></td><td><code>qalb id-</code></td><td><code>qalb it-</code></td></tr><tr><td>qrib</td><td>near</td><td><code>qrib il-</code></td><td><code>qrib l-</code></td><td><code>qrib is-</code></td><td><code>qrib id-</code></td><td><code>qrib it-</code></td></tr><tr><td>sakemm</td><td>until (introduces a clause)</td><td>not directly combined with a definite noun</td><td>not directly combined with a definite noun</td><td>not directly combined with a definite noun</td><td>not directly combined with a definite noun</td><td>not directly combined with a definite noun</td></tr><tr><td>waqt</td><td>at the time of; during</td><td><code>waqt il-</code></td><td><code>waqt l-</code></td><td><code>waqt is-</code></td><td><code>waqt id-</code></td><td><code>waqt it-</code></td></tr></tbody></table><p>Common contractions include <code>f&#39; / fi</code>, <code>b&#39; / bi</code>, <code>ma&#39;</code>, <code>għal</code>, <code>minn</code>, <code>ta&#39;</code>, <code>sa</code>, <code>lil</code>, <code>bħal</code>, and <code>ġo</code>. In phrases such as <code>faċċata ta&#39;</code> and <code>barra minn</code>, the <code>ta&#39;</code> or <code>minn</code> element contracts. Most other prepositions remain separate from the definite article. The <code>il-</code> and <code>l-</code> columns sometimes produce the same result in contracted forms; both are shown to compare the requested article spellings, not to imply separate rules.</p><h2 id="_3-direction-origin-and-location" tabindex="-1">3. Direction, Origin, and Location <a class="header-anchor" href="#_3-direction-origin-and-location" aria-label="Permalink to &quot;3. Direction, Origin, and Location&quot;">​</a></h2><ul><li><code>immur Malta</code>: I am going to Malta. (Place names do not always require an article.)</li><li><code>niġi minn Malta</code>: I come from Malta.</li><li><code>Il-ktieb qiegħed fuq il-mejda.</code>: The book is on the table.</li><li><code>Il-qattus qiegħed taħt is-sodda.</code>: The cat is under the bed.</li><li><code>L-iskola tinsab ħdejn id-dar.</code>: The school is next to the house.</li></ul><h2 id="_4-prepositions-of-time" tabindex="-1">4. Prepositions of Time <a class="header-anchor" href="#_4-prepositions-of-time" aria-label="Permalink to &quot;4. Prepositions of Time&quot;">​</a></h2><ul><li><code>filgħodu</code>: in the morning; <code>wara nofsinhar</code>: in the afternoon; <code>filgħaxija</code>: in the evening.</li><li><code>f&#39;Ġunju</code>: in June.</li><li><code>nhar it-Tnejn</code>: on Monday.</li><li><code>qabel l-ikel</code>: before the meal; <code>wara l-ikel</code>: after the meal.</li></ul><h2 id="_5-għand-for-have" tabindex="-1">5. <code>għand</code> for “Have” <a class="header-anchor" href="#_5-għand-for-have" aria-label="Permalink to &quot;5. `għand` for “Have”&quot;">​</a></h2><p>Maltese commonly uses a person form of <code>għand</code> to express possession rather than an English-style “have” verb:</p><table><thead><tr><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>I have</td><td>għandi</td></tr><tr><td>you have (singular)</td><td>għandek</td></tr><tr><td>he has</td><td>għandu</td></tr><tr><td>she has</td><td>għandha</td></tr><tr><td>we have</td><td>għandna</td></tr><tr><td>you have (plural)</td><td>għandkom</td></tr><tr><td>they have</td><td>għandhom</td></tr></tbody></table><p>Examples: <code>Għandi karozza.</code> (I have a car.) <code>Għandek kelb?</code> (Do you have a dog?)</p><h2 id="_6-study-tips" tabindex="-1">6. Study Tips <a class="header-anchor" href="#_6-study-tips" aria-label="Permalink to &quot;6. Study Tips&quot;">​</a></h2><p>Learn each preposition together with a noun rather than memorizing only one English gloss; <code>f&#39;</code>, <code>għal</code>, and <code>minn</code> can express different relationships depending on context. Notice contractions with articles, such as <code>fil-</code>, <code>bil-</code>, <code>mal-</code>, <code>għall-</code>, <code>mill-</code>, and <code>tal-</code>.</p><h2 id="_7-example-sentences-in-approximate-frequency-order" tabindex="-1">7. Example Sentences in Approximate Frequency Order <a class="header-anchor" href="#_7-example-sentences-in-approximate-frequency-order" aria-label="Permalink to &quot;7. Example Sentences in Approximate Frequency Order&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>Preposition</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>f&#39; / fi</td><td>I am in Malta.</td><td>Jien qiegħed f&#39;Malta.</td></tr><tr><td style="text-align:right;">2</td><td>b&#39; / bi</td><td>I open the door with a key.</td><td>Niftaħ il-bieb b&#39;ċavetta.</td></tr><tr><td style="text-align:right;">3</td><td>ma&#39;</td><td>I work with a friend.</td><td>Naħdem ma&#39; ħabib.</td></tr><tr><td style="text-align:right;">4</td><td>għal</td><td>This gift is for you.</td><td>Dan ir-rigal huwa għalik.</td></tr><tr><td style="text-align:right;">5</td><td>minn</td><td>She is from Malta.</td><td>Hi minn Malta.</td></tr><tr><td style="text-align:right;">6</td><td>ta&#39;</td><td>This is Anna&#39;s book.</td><td>Dan hu l-ktieb ta&#39; Anna.</td></tr><tr><td style="text-align:right;">7</td><td>fuq</td><td>The cup is on the table.</td><td>It-tazza qiegħda fuq il-mejda.</td></tr><tr><td style="text-align:right;">8</td><td>lil</td><td>I call my mother.</td><td>Inċempel lil ommi.</td></tr><tr><td style="text-align:right;">9</td><td>għand</td><td>I have a car.</td><td>Għandi karozza.</td></tr><tr><td style="text-align:right;">10</td><td>wara</td><td>We go after the meal.</td><td>Immorru wara l-ikla.</td></tr><tr><td style="text-align:right;">11</td><td>sa</td><td>I will stay until tomorrow.</td><td>Se nibqa&#39; sa għada.</td></tr><tr><td style="text-align:right;">12</td><td>lejn</td><td>The car is heading toward the port.</td><td>Il-karozza sejra lejn il-port.</td></tr><tr><td style="text-align:right;">13</td><td>taħt</td><td>The cat is under the chair.</td><td>Il-qattus qiegħed taħt is-siġġu.</td></tr><tr><td style="text-align:right;">14</td><td>bejn</td><td>The house is between the school and the shop.</td><td>Id-dar tinsab bejn l-iskola u l-ħanut.</td></tr><tr><td style="text-align:right;">15</td><td>qabel</td><td>I drink coffee before work.</td><td>Nixrob kafè qabel ix-xogħol.</td></tr><tr><td style="text-align:right;">16</td><td>ħdejn</td><td>The school is next to the house.</td><td>L-iskola tinsab ħdejn id-dar.</td></tr><tr><td style="text-align:right;">17</td><td>quddiem</td><td>The car is parked in front of the house.</td><td>Il-karozza qiegħda quddiem id-dar.</td></tr><tr><td style="text-align:right;">18</td><td>madwar</td><td>People are sitting around the table.</td><td>In-nies qegħdin bilqiegħda madwar il-mejda.</td></tr><tr><td style="text-align:right;">19</td><td>dwar</td><td>This book is about Malta.</td><td>Dan il-ktieb huwa dwar Malta.</td></tr><tr><td style="text-align:right;">20</td><td>minħabba</td><td>Because of the rain, we are staying at home.</td><td>Minħabba x-xita, nibqgħu d-dar.</td></tr><tr><td style="text-align:right;">21</td><td>bħal</td><td>She is like her mother.</td><td>Hi bħal ommha.</td></tr><tr><td style="text-align:right;">22</td><td>ġewwa</td><td>The children are inside the house.</td><td>It-tfal qegħdin ġewwa d-dar.</td></tr><tr><td style="text-align:right;">23</td><td>barra</td><td>We are outside the house.</td><td>Qegħdin barra mid-dar.</td></tr><tr><td style="text-align:right;">24</td><td>mingħajr</td><td>Coffee without sugar, please.</td><td>Kafè mingħajr zokkor, jekk jogħġbok.</td></tr><tr><td style="text-align:right;">25</td><td>kontra</td><td>The chair is against the wall.</td><td>Is-siġġu qiegħed kontra l-ħajt.</td></tr><tr><td style="text-align:right;">26</td><td>skont</td><td>According to the timetable, the bus leaves on time.</td><td>Skont l-iskeda, ix-xarabank jitlaq fil-ħin.</td></tr><tr><td style="text-align:right;">27</td><td>tul</td><td>There are many trees along the road.</td><td>Tul it-triq hemm ħafna siġar.</td></tr><tr><td style="text-align:right;">28</td><td>bla</td><td>Coffee without milk.</td><td>Kafè bla ħalib.</td></tr><tr><td style="text-align:right;">29</td><td>bħala</td><td>She works as a teacher.</td><td>Hi taħdem bħala għalliema.</td></tr><tr><td style="text-align:right;">30</td><td>biswit</td><td>The hotel is opposite the sea.</td><td>Il-lukanda tinsab biswit il-baħar.</td></tr><tr><td style="text-align:right;">31</td><td>faċċata ta&#39;</td><td>The bank is opposite the school.</td><td>Il-bank jinsab faċċata tal-iskola.</td></tr><tr><td style="text-align:right;">32</td><td>flok</td><td>I drink tea instead of coffee.</td><td>Nixrob tè flok kafè.</td></tr><tr><td style="text-align:right;">33</td><td>fost</td><td>The child is among his friends.</td><td>It-tifel qiegħed fost sħabu.</td></tr><tr><td style="text-align:right;">34</td><td>ġo</td><td>Put the book in a bag.</td><td>Poġġi l-ktieb ġo borża.</td></tr><tr><td style="text-align:right;">35</td><td>għajr</td><td>Everyone came except Ana.</td><td>Kulħadd ġie għajr Ana.</td></tr><tr><td style="text-align:right;">36</td><td>ħlief</td><td>Everything except this book.</td><td>Kollox ħlief dan il-ktieb.</td></tr><tr><td style="text-align:right;">37</td><td>maġenb</td><td>The shop is next to the house.</td><td>Il-ħanut qiegħed maġenb id-dar.</td></tr><tr><td style="text-align:right;">38</td><td>matul</td><td>The rain stopped during the night.</td><td>Ix-xita waqfet matul il-lejl.</td></tr><tr><td style="text-align:right;">39</td><td>minflok</td><td>I take the car instead of the bus.</td><td>Nieħu l-karozza minflok ix-xarabank.</td></tr><tr><td style="text-align:right;">40</td><td>minkejja</td><td>Despite the rain, we go out.</td><td>Minkejja x-xita, noħorġu.</td></tr><tr><td style="text-align:right;">41</td><td>qalb</td><td>The house is in the middle of the forest.</td><td>Id-dar tinsab qalb il-bosk.</td></tr><tr><td style="text-align:right;">42</td><td>qrib</td><td>I live near the school.</td><td>Ngħix qrib l-iskola.</td></tr><tr><td style="text-align:right;">43</td><td>sakemm</td><td>Wait until I arrive.</td><td>Stenna sakemm nasal.</td></tr><tr><td style="text-align:right;">44</td><td>waqt</td><td>The phone rang during the meeting.</td><td>Il-mowbajl daqq waqt il-laqgħa.</td></tr></tbody></table>',22),r=[i];function c(n,l,s,h,m,b){return d(),e("div",null,r)}const u=t(a,[["render",c]]);export{f as __pageData,u as default};
